# inspect component sizes/color compositions in the test grid
from collections import deque, Counter
h,w=len(test_grid),len(test_grid[0]); bg=Counter(v for row in test_grid for v in row).most_common(1)[0][0]
seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if test_grid[r][c]==bg or (r,c) in seen: continue
  q=deque([(r,c)]); seen.add((r,c)); cc=[]
  while q:
   y,x=q.popleft(); cc.append((y,x))
   for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and test_grid[yy][xx]!=bg:
     seen.add((yy,xx)); q.append((yy,xx))
  comps.append(cc)
print(bg, sorted([(len(c),Counter(test_grid[r][x] for r,x in c),c) for c in comps],reverse=True,key=lambda x:x[0])[:10])

